        .topbar{height:68px;background:var(--nav);color:#fff;display:flex;align-items:center;padding:0 28px;gap:18px;position:sticky;top:0;z-index:20}.brand{display:flex;align-items:center;gap:11px;font-weight:800;letter-spacing:.04em}.brand-mark{width:35px;height:35px;border-radius:10px;background:linear-gradient(135deg,#6c8cff,#3458c9);display:grid;place-items:center}.top-sep{height:28px;width:1px;background:#ffffff2b}.crumb{font-size:14px;color:#cbd4e6}.top-actions{margin-left:auto;display:flex;gap:10px}.btn{border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:10px;padding:10px 14px;font-size:13px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;gap:8px;text-decoration:none;transition:.18s}.btn:hover{transform:translateY(-1px);box-shadow:0 5px 16px #17203314}.btn-primary{background:var(--blue);border-color:var(--blue);color:#fff}.btn-ghost{background:transparent;color:#e6ebf7;border-color:#ffffff38}.btn-danger{color:var(--red)}
