ition:relative}.connector::after{content:"";position:absolute;left:-3px;bottom:0;border-left:4px solid transparent;border-right:4px solid transparent;border-top:6px solid #ccd4df}.empty{padding:50px;text-align:center;color:var(--muted)}.doc-footer{display:flex;justify-content:space-between;border-top:1px solid var(--line);margin-top:28px;padding-top:16px;font-size:10px;color:#8992a1;text-transform:uppercase;letter-spacing:.08em}.toast{position:fixed;right:24px;bottom:24px;background:#172033;color:#fff;border-radius:11px;padding:13px 17px;font-size:13px;box-shadow:var(--shadow);opacity:0;transform:translateY(10px);pointer-events:none;transition:.25s;z-index:99}.toast.show{opacity:1;transform:none}
        .step-fields{min-width:0}.step-input{width:100%}.step-path-input{width:100%;margin-top:7px;border:1px solid var(--line);border-radius:7px;padding:6px 8px;font-size:11px;background:#fff;color:#5d687a}.badge-editor{display:flex;align-items:center;gap:6px;margin-top:7px}.badge-input{min-width:0;width:130px;border:1px solid var(--line);border-radius:7px;padding:5px 7px;font-size:11px;background:#fff}.badge-color{width:28px;height:27px;border:0;background:transparent;padding:0}.library-row{display:grid;grid-template-columns:1fr auto;gap:7px;align-items:start}.procedure-search{position:relative;min-width:0}.procedure-search-input{width:100%;border:1px solid var(--line);border-radius:10px;padding:10px 34px 10px 12px;outline:none;background:#fff}.procedure-search-input:focus{border-color:#8da5ed;box-shadow:0 0 0 3px #4169e118}.procedure-search-icon{position:absolute;right:11px;top:11px;color:#8791a1;pointer-events:none}.procedure-search-results{position:absolute;z-index:50;left:0;right:0;top:calc(100% + 5px);max-height:245px;overflow:auto;border:1px solid var(--line);border-radius:12px;background:#fff;box-shadow:0 16px 35px #17203320;padding:5px}.procedure-search-results[hidden]{display:none}.procedure-result{display:block;width:100%;border:0;background:#fff;border-radius:8px;padding:9px 10px;text-align:left;color:var(--ink)}.procedure-result:hover,.procedure-result.active{background:var(--blue-soft);color:var(--blue)}.procedure-result strong{display:block;font-size:12px}.procedure-result small{display:block;margin-top:2px;color:var(--muted);font-size:10px}.procedure-empty{padding:13px;text-align:center;color:var(--muted);font-size:12px}.color-row{display:grid;grid-template-columns:1fr 52px;gap:8px}.save-status{font-size:11px;color:var(--green);font-weight:700;text-align:center;margin-top:7px;min-height:16px}.breadcrumb-wrap{margin:0 0 25px;padding:15px;border:1px solid var(--line);border-radius:12px;background:#f8fafc}.breadcrumb-title{display:flex;align-items:center;gap:8px;margin-bottom:11px;color:var(--accent);font-size:10px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.breadcrumb-title::before{content:"⌖";display:grid;place-items:center;width:22px;height:22px;border-radius:7px;background:var(--accent);color:#fff;font-size:13px}.breadcrumb{display:flex;align-items:center;gap:6px;overflow-x:auto;padding:2px 1px 5px}.breadcrumb button{flex:0 0 auto;border:1px solid #dce2eb;background:#fff;color:#566175;border-radius:9px;padding:8px 11px;font-size:11px;font-weight:800;max-width:165px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.breadcrumb button:hover,.breadcrumb button.active{border-color:var(--accent);background:var(--accent);color:#fff;box-shadow:0 4px 12px #17203318}.breadcrumb span{font-size:15px;color:#9ba5b4;font-weight:800}.flow-step{border-left-color:var(--step-color,var(--accent,var(--blue)));cursor:grab;transition:.18s}.flow-step:active{cursor:grabbing}.flow-step.dragging{opacity:.35}.flow-step.drag-over{transform:translateY(5px);box-shadow:0 -3px 0 var(--accent)}.flow-meta{display:flex;align-items:center;gap:8px;margin-top:5px}.flow-content .flow-meta small{margin-top:0}.line-badge{display:inline-flex;border-radius:20px;padding:3px 8px;color:#fff;font-size:9px;font-weight:850;letter-spacing:.04em;text-transform:uppercase}.menu-path{margin-top:10px;padding:9px 11px;border:1px solid #e6eaf0;border-radius:9px;background:#f8fafc}.menu-path-label{display:block;margin-bottom:6px;color:#9aa3b1;font-size:8px;font-weight:700;letter-spacing:.14em;text-transform:uppercase}.menu-path-label::before{content:"⌖";margin-right:5px;font-size:10px}.menu-path-trail{display:flex;align-items:center;flex-wrap:wrap;gap:0}.menu-path-item{display:inline-flex;align-items:center;color:#344054;font-size:11px;font-weight:800;line-height:1.3}.menu-path-item:not(:last-child)::after{content:"›";margin:0 8px;color:#a7b0bd;font-size:16px;font-weight:500}.menu-path-item:last-child{color:#fff;background:var(--accent);border-radius:6px;padding:4px 8px;box-shadow:0 3px 8px #17203316}
        @media(max-width:920px){.shell{display:block}.sidebar{border-right:0;border-bottom:1px solid var(--line)}.workspace{padding:20px}.canvas-wrap{padding:16px}.canvas{padding:38px 28px}.topbar{padding:0 16px}.crumb{display:none}.workspace-head{display:block}.export-menu{margin-top:15px}.doc-header{display:block}.doc-badge{display:inline-block;margin-top:14px}}
        @media print{body{background:#fff}.topbar,.sidebar,.workspace-head{display:none!important}.shell{display:block}.workspace,.canvas-wrap{padding:0;background:#fff}.canvas{box-shadow:none;width:100%;min-height:0;padding:24px 36px}.flow-step{break-inside:avoid}.connector{height:18px}@page{size:A4;margin:12mm}}
