<body>
<header class="topbar">
    <div class="brand"><span class="brand-mark">F</span> FINEA</div><span class="top-sep"></span><span class="crumb">Organisation &nbsp;/&nbsp; Atelier de procédures</span>
    <div class="top-actions"><a class="btn btn-ghost" href="../selection_portail.php">← Portail</a><button class="btn btn-ghost" id="newProcedure">＋ Nouvelle</button><button class="btn btn-primary" id="saveProcedure">✓ Enregistrer</button></div>
</header>
<main class="shell">
    <aside class="sidebar">
        <div class="eyebrow">Concepteur visuel</div>
