        <p class="helper">Choisissez un modèle, adaptez les étapes puis exportez un schéma clair à partager.</p>
        <div class="section-title"><span>Mes procédures</span></div>
        <div class="library-row"><div class="procedure-search"><input type="search" id="procedureSearch" class="procedure-search-input" placeholder="Rechercher une procédure…" autocomplete="off"><span class="procedure-search-icon">⌕</span><div id="procedureSearchResults" class="procedure-search-results" hidden></div><select id="savedProcedures" hidden><option value=""></option></select></div><button class="btn btn-danger" id="deleteProcedure" title="Supprimer">×</button></div>
        <div class="save-status" id="saveStatus"></div>
        <div class="section-title"><span>Modèles FINEA</span></div>
        <div class="templates" id="templates"></div>
        <div class="section-title"><span>Informations</span></div>
        <div class="field"><label for="title">Nom de la procédure</label><input id="title" maxlength="100"></div>
        <div class="field"><label for="description">Objectif</label><textarea id="description" maxlength="280"></textarea></div>
        <div class="field"><label for="color">Couleur du schéma</label><select id="color"><option value="blue">Bleu FINEA</option><option value="green">Vert validation</option><option value="orange">Orange opérationnel</option><option value="red">Rouge contrôle</option><option value="custom">Couleur personnalisée</option></select></div>
        <div class="field" id="customColorField"><label for="customColor">Code hexadécimal</label><div class="color-row"><input id="customColor" maxlength="7" placeholder="#4169E1"><input type="color" id="customColorPicker" value="#4169e1"></div></div>
        <div class="section-title"><span>Étapes</span><small id="stepCount"></small></div>
        <div class="step-list" id="stepList"></div>
        <button class="add-step" id="addStep">＋ Ajouter une étape</button>
