<div class="toast" id="toast"></div>
<script>
(() => {
    const makeSteps = rows => rows.map(title => ({title,path:'',badge:'',badgeColor:'#4169e1'}));
    const templates = [
        {id:'chantier',icon:'C',title:'Démarrage d’un chantier',description:'Cadrer et lancer un nouveau chantier dans FINEA, du devis jusqu’à la première FEB.',color:'blue',customColor:'#4169e1',steps:makeSteps(['Créer la fiche du nouveau chantier','Importer et rattacher le devis validé','Définir les dates et construire le planning','Établir le déboursé selon le planning','Contrôler les données de lancement','Créer la première FEB'])},
        {id:'feb',icon:'F',title:'Traitement d’une FEB',description:'Sécuriser le circuit d’une fiche d’expression de besoin jusqu’à sa régularisation.',color:'green',customColor:'#168a65',steps:makeSteps(['Créer et renseigner la FEB','Réaliser le devis contradictoire','Faire valider par les directeurs concernés','Créer le bon de commande interne (BCI)','Obtenir la validation du service Achats','Vérifier les pièces justificatives (FNE, PV, etc.)','Créer le récapitulatif des décaissements','Obtenir la signature de la Direction générale','Éditer et remettre le chèque','Régulariser le dossier (décharge, copie du chèque, etc.)'])},
        {id:'contrat',icon:'K',title:'Contrat de sous-traitance',description:'Constituer un contrat complet, contrôlable et exploitable pour le suivi de la prestation.',color:'orange',customColor:'#e77732',steps:makeSteps(['Identifier le sous-traitant (NCC, RCCM et coordonnées)','Définir l’objet et décrire précisément la prestation','Fixer la durée et le planning d’exécution','Lister les intervenants autorisés','Valider le mode opératoire','Définir les exigences HSE','Arrêter le prix et les coûts de la prestation','Définir les modalités de paiement','Préciser les pénalités de retard','Lister les pièces requises au paiement (FNE, PV, BC, etc.)','Fixer le délai de traitement des factures','Définir la procédure en cas de litige','Faire signer les parties'])}
    ];
    const palette={blue:['#4169e1','#edf2ff'],green:['#168a65','#e8f7f1'],orange:['#e77732','#fff2e8'],red:['#d44c5c','#fdecef']};
    const $=id=>document.getElementById(id), escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
    const clone=value=>JSON.parse(JSON.stringify(value));
    const normalize = data => {const item=data&&typeof data==='object'?data:clone(templates[0]);item.steps=Array.isArray(item.steps)?item.steps.map(s=>typeof s==='string'?{title:s,path:'',badge:'',badgeColor:'#4169e1'}:{title:String(s.title||''),path:String(s.path||''),badge:String(s.badge||''),badgeColor:validHex(s.badgeColor)?s.badgeColor:'#4169e1'}):[];item.customColor=validHex(item.customColor)?item.customColor:(palette[item.color]?.[0]||'#4169e1');return item};
    let active='chantier', state=normalize(loadDraft()||clone(templates[0])), savedId=state.savedId||'';
    function validHex(value){return /^#[0-9a-f]{6}$/i.test(String(value||''))}
    function loadDraft(){try{return JSON.parse(localStorage.getItem('finea_procedure_draft'))}catch(e){return null}}
    function getLibrary(){try{const rows=JSON.parse(localStorage.getItem('finea_procedures')||'[]');return Array.isArray(rows)?rows:[]}catch(e){return []}}
    function saveDraft(){state.savedId=savedId;localStorage.setItem('finea_procedure_draft',JSON.stringify(state));$('saveStatus').textContent=savedId?'Modifications non enregistrées':'Brouillon en cours'}
    function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2200)}
    function renderLibrary(){const rows=getLibrary(),selected=rows.find(x=>x.savedId===savedId);$('savedProcedures').innerHTML='<option value=""></option>'+rows.map(x=>`<option value="${escape(x.savedId)}" ${x.savedId===savedId?'selected':''}>${escape(x.title||'Sans titre')}</option>`).join('');$('procedureSearch').value=selected?selected.title||'Sans titre':'';renderProcedureResults('')}
    function renderProcedureResults(query){const q=String(query||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''),rows=getLibrary().filter(x=>!q||String(x.title||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q));$('procedureSearchResults').innerHTML=rows.length?rows.map(x=>`<button type="button" class="procedure-result ${x.savedId===savedId?'active':''}" data-open-procedure="${escape(x.savedId)}"><strong>${escape(x.title||'Sans titre')}</strong><small>${Array.isArray(x.steps)?x.steps.length:0} étapes${x.updatedAt?' · modifiée le '+new Date(x.updatedAt).toLocaleDateString('fr-FR'):''}</small></button>`).join(''):'<div class="procedure-empty">Aucune procédure trouvée</div>';document.querySelectorAll('[data-open-procedure]').forEach(b=>b.onclick=()=>{const select=$('savedProcedures');select.value=b.dataset.openProcedure;select.dispatchEvent(new Event('change'));$('procedureSearchResults').hidden=true})}
    function renderTemplates(){$('templates').innerHTML=templates.map(t=>`<button class="template ${active===t.id?'active':''}" data-id="${t.id}"><span class="template-icon">${t.icon}</span><span><strong>${escape(t.title)}</strong><small>${t.steps.length} étapes</small></span></button>`).join('');document.querySelectorAll('.template').forEach(b=>b.onclick=()=>{const t=templates.find(x=>x.id===b.dataset.id);if(!t)return;active=t.id;savedId='';state=normalize(clone(t));sync();toast('Modèle chargé comme nouveau brouillon')})}
    function renderEditors(){$('stepCount').textContent=state.steps.length;$('stepList').innerHTML=state.steps.map((s,i)=>`<div class="step-editor"><span class="step-number">${i+1}</span><div class="step-fields"><input class="step-input" value="${escape(s.title)}" aria-label="Étape ${i+1}" data-step="${i}"><input class="step-path-input" data-path="${i}" value="${escape(s.path)}" placeholder="Chemin FINEA : Portail > Module > Action"><div class="badge-editor"><input class="badge-input" data-badge="${i}" value="${escape(s.badge)}" placeholder="Badge (optionnel)"><input type="color" class="badge-color" data-badge-color="${i}" value="${validHex(s.badgeColor)?s.badgeColor:'#4169e1'}" title="Couleur du badge"></div></div><span class="step-tools"><button class="icon-btn" title="Monter" data-up="${i}">↑</button><button class="icon-btn" title="Descendre" data-down="${i}">↓</button><button class="icon-btn" title="Supprimer" data-delete="${i}">×</button></span></div>`).join('');document.querySelectorAll('[data-step]').forEach(el=>el.oninput=()=>updateStep(+el.dataset.step,'title',el.value));document.querySelectorAll('[data-path]').forEach(el=>el.oninput=()=>updateStep(+el.dataset.path,'path',el.value));document.querySelectorAll('[data-badge]').forEach(el=>el.oninput=()=>updateStep(+el.dataset.badge,'badge',el.value));document.querySelectorAll('[data-badge-color]').forEach(el=>el.oninput=()=>updateStep(+el.dataset.badgeColor,'badgeColor',el.value));document.querySelectorAll('[data-up]').forEach(el=>el.onclick=()=>move(+el.dataset.up,-1));document.querySelectorAll('[data-down]').forEach(el=>el.onclick=()=>move(+el.dataset.down,1));document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=()=>{state.steps.splice(+el.dataset.delete,1);sync(false)})}
    function updateStep(i,key,value){state.steps[i][key]=value;saveDraft();renderCanvas()}
    function move(i,d){const n=i+d;if(n<0||n>=state.steps.length)return;[state.steps[i],state.steps[n]]=[state.steps[n],state.steps[i]];sync(false)}
    function pathMarkup(path){const parts=String(path||'').split(/\s*(?:>|›)\s*/).map(x=>x.trim()).filter(Boolean);return parts.length?`<div class="menu-path"><span class="menu-path-label">Chemin dans FINEA</span><div class="menu-path-trail">${parts.map(x=>`<span class="menu-path-item">${escape(x)}</span>`).join('')}</div></div>`:''}
    function renderCanvas(){const base=state.color==='custom'&&validHex(state.customColor)?state.customColor:(palette[state.color]?.[0]||'#4169e1'),p=[base,base+'18'];$('canvas').style.setProperty('--accent',p[0]);$('canvas').style.setProperty('--accent-soft',p[1]);const steps=state.steps.map((s,index)=>({...s,index})).filter(x=>x.title.trim());$('canvas').innerHTML=`<header class="doc-header"><div><div class="doc-kicker">Procédure opérationnelle</div><h1 class="doc-title">${escape(state.title||'Sans titre')}</h1><p class="doc-description">${escape(state.description||'Décrivez ici l’objectif de cette procédure.')}</p></div><span class="doc-badge">${steps.length} ÉTAPE${steps.length>1?'S':''}</span></header>${steps.length?`<div class="breadcrumb-wrap"><div class="breadcrumb-title">Parcours de la procédure</div><nav class="breadcrumb" aria-label="Fil d’Ariane de la procédure">${steps.map((s,i)=>`${i?'<span aria-hidden="true">›</span>':''}<button data-jump="${s.index}" title="Aller à : ${escape(s.title)}"><b>${i+1}</b>&nbsp; ${escape(s.title)}</button>`).join('')}</nav></div><div class="flow">${steps.map((s,i)=>`<div class="flow-step" draggable="true" data-drag-index="${s.index}" id="procedure-step-${s.index}" style="--step-color:${validHex(s.badgeColor)&&s.badge?s.badgeColor:base}"><span class="flow-number">${String(i+1).padStart(2,'0')}</span><span class="flow-content"><strong>${escape(s.title)}</strong><span class="flow-meta"><small>Étape ${i+1} sur ${steps.length}</small>${s.badge?`<span class="line-badge" style="background:${validHex(s.badgeColor)?s.badgeColor:base}">${escape(s.badge)}</span>`:''}</span>${pathMarkup(s.path)}</span><span class="flow-check"></span></div>${i<steps.length-1?'<span class="connector"></span>':''}`).join('')}</div>`:'<div class="empty">Ajoutez une première étape pour construire le schéma.</div>'}<footer class="doc-footer"><span>FINEA · Référentiel des procédures</span><span>Édité le ${new Intl.DateTimeFormat('fr-FR').format(new Date())}</span></footer>`;bindCanvasInteractions()}
    function bindCanvasInteractions(){document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-jump]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('procedure-step-'+b.dataset.jump)?.scrollIntoView({behavior:'smooth',block:'center'})});let source=-1;document.querySelectorAll('[data-drag-index]').forEach(row=>{row.ondragstart=e=>{source=+row.dataset.dragIndex;row.classList.add('dragging');e.dataTransfer.effectAllowed='move'};row.ondragend=()=>{row.classList.remove('dragging');document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'))};row.ondragover=e=>{e.preventDefault();row.classList.add('drag-over')};row.ondragleave=()=>row.classList.remove('drag-over');row.ondrop=e=>{e.preventDefault();const target=+row.dataset.dragIndex;if(source<0||source===target)return;const [item]=state.steps.splice(source,1);state.steps.splice(target,0,item);sync(false);toast('Ordre des étapes modifié')}})}
    function sync(full=true){$('title').value=state.title||'';$('description').value=state.description||'';$('color').value=state.color||'blue';$('customColor').value=state.customColor||'#4169e1';$('customColorPicker').value=validHex(state.customColor)?state.customColor:'#4169e1';$('customColorField').style.display=state.color==='custom'?'block':'none';if(full){renderTemplates();renderLibrary()}renderEditors();renderCanvas();saveDraft()}
    function slug(){return (state.title||'procedure-finea').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
    function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
    function svgMarkup(){const steps=state.steps.filter(x=>x.title.trim()),base=state.color==='custom'&&validHex(state.customColor)?state.customColor:(palette[state.color]?.[0]||'#4169e1'),w=1100,h=210+steps.length*108;const wrap=(s,max=72)=>{const words=s.split(/\s+/);let lines=[''];words.forEach(word=>{const last=lines.length-1;if((lines[last]+' '+word).trim().length>max)lines.push(word);else lines[last]=(lines[last]+' '+word).trim()});return lines.slice(0,2)};return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><rect width="100%" height="100%" fill="#fff"/><rect width="100%" height="9" fill="${base}"/><style>text{font-family:Arial,sans-serif}.t{font-size:34px;font-weight:700;fill:#172033}.d{font-size:15px;fill:#687386}.n{font-size:16px;font-weight:700;fill:${base}}.s{font-size:17px;font-weight:700;fill:#172033}.m{font-size:12px;fill:#687386}.b{font-size:10px;font-weight:700;fill:#fff}.p{font-size:11px;font-weight:700;fill:${base}}</style><text x="65" y="55" class="n">PROCÉDURE OPÉRATIONNELLE</text><text x="65" y="100" class="t">${escape(state.title)}</text><text x="65" y="134" class="d">${escape((state.description||'').slice(0,105))}</text>${steps.map((s,i)=>{const y=175+i*108,lines=wrap(s.title),bc=validHex(s.badgeColor)?s.badgeColor:base;return `<rect x="65" y="${y}" width="970" height="86" rx="12" fill="#fff" stroke="#e4e9f0"/><rect x="65" y="${y}" width="5" height="86" rx="2" fill="${s.badge?bc:base}"/><circle cx="111" cy="${y+35}" r="23" fill="${base}18"/><text x="111" y="${y+41}" text-anchor="middle" class="n">${i+1}</text>${lines.map((l,j)=>`<text x="155" y="${y+29+j*21}" class="${j?'m':'s'}">${escape(l)}</text>`).join('')}${s.path?`<text x="155" y="${y+70}" class="p">CHEMIN FINEA · ${escape(s.path.slice(0,105))}</text>`:''}${s.badge?`<rect x="830" y="${y+23}" width="130" height="24" rx="12" fill="${bc}"/><text x="895" y="${y+39}" text-anchor="middle" class="b">${escape(s.badge.slice(0,18))}</text>`:''}`}).join('')}<text x="65" y="${h-25}" class="m">FINEA · Référentiel des procédures</text></svg>`}
    $('title').oninput=e=>{state.title=e.target.value;active='';saveDraft();renderTemplates();renderCanvas()};$('description').oninput=e=>{state.description=e.target.value;saveDraft();renderCanvas()};$('color').onchange=e=>{state.color=e.target.value;sync(false)};$('customColor').oninput=e=>{if(validHex(e.target.value)){state.customColor=e.target.value;$('customColorPicker').value=e.target.value;saveDraft();renderCanvas()}};$('customColorPicker').oninput=e=>{state.customColor=e.target.value;$('customColor').value=e.target.value;saveDraft();renderCanvas()};$('addStep').onclick=()=>{state.steps.push({title:'Nouvelle étape',path:'',badge:'',badgeColor:'#4169e1'});sync(false);setTimeout(()=>{const inputs=document.querySelectorAll('[data-step]');inputs[inputs.length-1]?.select()},0)};$('newProcedure').onclick=()=>{active='';savedId='';state=normalize({id:'custom',title:'Nouvelle procédure',description:'Décrivez l’objectif et le résultat attendu.',color:'blue',customColor:'#4169e1',steps:[{title:'Première étape',path:'',badge:'',badgeColor:'#4169e1'}]});sync();toast('Nouveau brouillon créé')};
    $('saveProcedure').onclick=()=>{const rows=getLibrary();if(!savedId)savedId='procedure-'+Date.now();state.savedId=savedId;state.updatedAt=new Date().toISOString();const index=rows.findIndex(x=>x.savedId===savedId);if(index>=0)rows[index]=clone(state);else rows.unshift(clone(state));localStorage.setItem('finea_procedures',JSON.stringify(rows));localStorage.setItem('finea_procedure_draft',JSON.stringify(state));renderLibrary();$('saveStatus').textContent='Enregistrée à '+new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});toast('Procédure enregistrée')};$('savedProcedures').onchange=e=>{const found=getLibrary().find(x=>x.savedId===e.target.value);if(!found)return;savedId=found.savedId;active='';state=normalize(clone(found));sync();$('saveStatus').textContent='Procédure enregistrée';toast('Procédure ouverte')};$('procedureSearch').onfocus=e=>{renderProcedureResults(e.target.value);$('procedureSearchResults').hidden=false};$('procedureSearch').oninput=e=>{renderProcedureResults(e.target.value);$('procedureSearchResults').hidden=false};$('procedureSearch').onkeydown=e=>{if(e.key==='Escape'){$('procedureSearchResults').hidden=true;e.target.blur()}};document.addEventListener('click',e=>{if(!e.target.closest('.procedure-search'))$('procedureSearchResults').hidden=true});$('deleteProcedure').onclick=()=>{if(!savedId)return toast('Aucune procédure enregistrée sélectionnée');if(!confirm('Supprimer cette procédure enregistrée ?'))return;localStorage.setItem('finea_procedures',JSON.stringify(getLibrary().filter(x=>x.savedId!==savedId)));savedId='';state.savedId='';renderLibrary();saveDraft();toast('Procédure supprimée')};
    $('exportJson').onclick=()=>{download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),slug()+'.json');toast('Fichier JSON exporté')};$('exportSvg').onclick=()=>{download(new Blob([svgMarkup()],{type:'image/svg+xml'}),slug()+'.svg');toast('Schéma SVG exporté')};$('exportPng').onclick=()=>{const svg=svgMarkup(),img=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));img.onload=()=>{const c=document.createElement('canvas');c.width=img.width*1.5;c.height=img.height*1.5;const ctx=c.getContext('2d');ctx.scale(1.5,1.5);ctx.drawImage(img,0,0);c.toBlob(b=>download(b,slug()+'.png'),'image/png');URL.revokeObjectURL(url);toast('Image PNG exportée')};img.src=url};$('exportPdf').onclick=()=>window.print();
    sync();
})();
</script>
</body>
</html>
